SegaScreen:
		move.b	#CmdID_Stop,d0
		bsr.w	PlaySound
		bsr.w	ClearPLC
		bsr.w	Pal_FadeToBlack
		lea	(VDP_control_port).l,a6
		move.w	#$8004,(a6)
		move.w	#$8230,(a6)
		move.w	#$8407,(a6)
		move.w	#$8700,(a6)
		move.w	#$8B00,(a6)
		move.w	#$8C81,(a6)
		clr.b	(Water_fullscreen_flag).w
		move	#$2700,sr
		move.w	(VDP_Reg1_val).w,d0
		andi.b	#$BF,d0
		move.w	d0,(VDP_control_port).l
		bsr.w	ClearScreen
		move.l	#$40000000,(VDP_control_port).l
		lea	(Nem_SegaLogo).l,a0
		bsr.w	NemDec
		lea	(Chunk_Table).l,a1
		lea	(Eni_SegaLogo).l,a0
		move.w	#0,d0
		bsr.w	EniDec
		lea	(Chunk_Table).l,a1
		move.l	#$65100003,d0
		moveq	#$17,d1
		moveq	#7,d2
		bsr.w	PlaneMapToVRAM_H40
		lea	(Chunk_Table+$180).l,a1
		move.l	#$40000003,d0
		moveq	#$27,d1
		moveq	#$1B,d2
		bsr.w	PlaneMapToVRAM_H40
		tst.b	(Graphics_flags).w	; is console Japanese?
		bmi.s	loc_316A	; if not, branch
		; hide 'TM' symbol
		lea	(Chunk_Table+$A40).l,a1
		move.l	#$453A0003,d0
		moveq	#2,d1
		moveq	#1,d2
		bsr.w	PlaneMapToVRAM_H40

loc_316A:
		moveq	#PalID_Sega,d0
		bsr.w	PalLoad2
		move.w	#-$A,(PalCycle_Frame).w
		move.w	#0,(PalCycle_Timer).w
		move.w	#0,(unk_F662).w
		move.w	#0,(unk_F660).w
		move.w	(VDP_Reg1_val).w,d0
		ori.b	#$40,d0
		move.w	d0,(VDP_control_port).l

Sega_WaitPalette:
		move.b	#VintID_SEGA,(Vint_routine).w
		bsr.w	WaitForVint
		bsr.w	PalCycle_Sega
		bne.s	Sega_WaitPalette

		move.b	#CmdID_SegaSound,d0
		bsr.w	PlaySound
		move.b	#VintID_PCM,(Vint_routine).w
		bsr.w	WaitForVint
		move.w	#$1E,(Demo_Time_left).w

Sega_WaitEnd:
		move.b	#VintID_SEGA,(Vint_routine).w
		bsr.w	WaitForVint
		tst.w	(Demo_Time_left).w
		beq.s	Sega_GoToTitleScreen
		andi.b	#$80,(Ctrl_1_Press).w
		beq.s	Sega_WaitEnd

Sega_GoToTitleScreen:
		move.b	#GameModeID_TitleScreen,(Game_Mode).w
		rts
; ===========================================================================
		dc.w 0
; ===========================================================================

TitleScreen:				; CODE XREF: ROM:000003A0j
		move.b	#CmdID_Stop,d0
		bsr.w	PlaySound
		bsr.w	ClearPLC
		bsr.w	Pal_FadeToBlack
		move	#$2700,sr
		bsr.w	SoundDriverLoad

		lea	(VDP_control_port).l,a6
		move.w	#$8004,(a6)		; horizontal interrupts disabled
		move.w	#$8230,(a6)		; Plane A at $C000
		move.w	#$8407,(a6)		; Plane B at $E000
		move.w	#$9001,(a6)		; 64x32 scroll window
		move.w	#$9200,(a6)		; disable Window plane
		move.w	#$8B03,(a6)		; scroll per-row horizontally, full-screen vertically
		move.w	#$8720,(a6)		; set background color to palette line 2, color 0
		clr.b	(Water_fullscreen_flag).w
		move.w	#$8C81,(a6)		; 40 cells, no interlace, S/H disabled
		bsr.w	ClearScreen

		clearRAM Sprite_Input_Table
		clearRAM Object_RAM
		clearRAM Misc_Variables
		clearRAM Camera_RAM
		clearRAM Target_palette

		moveq	#PalID_SonicTails,d0
		bsr.w	PalLoad1
		bsr.w	Pal_FadeFromBlack

		move	#$2700,sr
		move.l	#$40000000,(VDP_control_port).l
		lea	(Nem_Title).l,a0
		bsr.w	NemDec
		move.l	#$40000001,(VDP_control_port).l
		lea	(Nem_TitleSonicTails).l,a0
		bsr.w	NemDec
		lea	(VDP_data_port).l,a6
		move.l	#$50000003,4(a6)
		lea	(Art_Text).l,a5
		move.w	#$28F,d1

loc_32C4:
		move.w	(a5)+,(a6)
		dbf	d1,loc_32C4
		nop
		move.b	#0,(Last_star_pole_hit).w
		move.w	#0,(Debug_placement_mode).w
		move.w	#0,(Demo_mode_flag).w
		move.w	#0,(unk_FFEA).w
		move.w	#0,(Current_ZoneAndAct).w
		move.w	#0,(PalCycle_Timer).w
		bsr.w	Pal_FadeToBlack
		move	#$2700,sr

		lea	(Chunk_Table).l,a1
		lea	(Eni_TitleMap).l,a0
		move.w	#0,d0
		bsr.w	EniDec
		lea	(Chunk_Table).l,a1
		move.l	#$40000003,d0
		moveq	#$27,d1
		moveq	#$1B,d2
		bsr.w	PlaneMapToVRAM_H40

		lea	(Chunk_Table).l,a1
		lea	(Eni_TitleBg1).l,a0
		move.w	#0,d0
		bsr.w	EniDec
		lea	(Chunk_Table).l,a1
		move.l	#$60000003,d0
		moveq	#$1F,d1
		moveq	#$1B,d2
		bsr.w	PlaneMapToVRAM_H40

		lea	(Chunk_Table).l,a1
		lea	(Eni_TitleBg2).l,a0
		move.w	#0,d0
		bsr.w	EniDec
		lea	(Chunk_Table).l,a1
		move.l	#$60400003,d0
		moveq	#$1F,d1
		moveq	#$1B,d2
		bsr.w	PlaneMapToVRAM_H40

		moveq	#PalID_Title,d0
		bsr.w	PalLoad1
		move.b	#MusID_Title,d0
		bsr.w	PlaySound

		move.b	#0,(Debug_mode_flag).w
		move.w	#0,(Two_player_mode).w
		move.w	#$178,(Demo_Time_left).w
		clearRAM Object_RAM+$80,Object_RAM+$C0

		move.b	#ObjID_TitleCharacters,(TitleSonic+id).w
		move.b	#ObjID_TitleCharacters,(TitleTails+id).w
		move.b	#1,(TitleTails+mapping_frame).w
		jsr	(RunObjects).l
		jsr	(BuildSprites).l
		moveq	#PLCID_Main,d0
		bsr.w	LoadPLC2
		move.w	#0,(Correct_cheat_entries).w
		move.w	#0,(Correct_cheat_entries_2).w
		move.w	#$300,(Current_ZoneAndAct).w
		move.w	#4,(Sonic_Pos_Record_Index).w
		move.w	#0,(Sonic_Pos_Record_Buf).w
		move.w	(VDP_Reg1_val).w,d0
		ori.b	#$40,d0
		move.w	d0,(VDP_control_port).l
		bsr.w	Pal_FadeFromBlack

TitleScreen_Loop:
		move.b	#VintID_Title,(Vint_routine).w
		bsr.w	WaitForVint
		jsr	(RunObjects).l
		bsr.w	Deform_TitleScreen
		jsr	(BuildSprites).l
		bsr.w	RunPLC_RAM
		tst.b	(Graphics_flags).w	; is this a Japanese Mega Drive?
		bpl.s	Title_RegionJ		; if yes, branch
		lea	(LvlSelCode_US).l,a0	; use NTSC-U/PAL combination
		bra.s	LevelSelectCheat
; ===========================================================================

Title_RegionJ:
		lea	(LvlSelCode_J).l,a0	; use NTSC-J combination (identical)

LevelSelectCheat:
		move.w	(Correct_cheat_entries).w,d0
		adda.w	d0,a0
		move.b	(Ctrl_1_Press).w,d0
		andi.b	#$F,d0
		cmp.b	(a0),d0
		bne.s	Title_Cheat_NoMatch
		addq.w	#1,(Correct_cheat_entries).w
		tst.b	d0
		bne.s	Title_Cheat_CountC
		lea	(Level_select_flag).w,a0
		move.w	(Correct_cheat_entries_2).w,d1
		lsr.w	#1,d1
		andi.w	#3,d1
		beq.s	Title_Cheat_PlayRing
		tst.b	(Graphics_flags).w
		bpl.s	Title_Cheat_PlayRing
		moveq	#1,d1
		move.b	d1,1(a0,d1.w)

Title_Cheat_PlayRing:
		move.b	#1,(a0,d1.w)
		move.b	#SndID_Ring,d0
		bsr.w	PlaySound
		bra.s	Title_Cheat_CountC
; ===========================================================================

Title_Cheat_NoMatch:
		tst.b	d0
		beq.s	Title_Cheat_CountC
		cmpi.w	#9,(Correct_cheat_entries).w
		beq.s	Title_Cheat_CountC
		move.w	#0,(Correct_cheat_entries).w

Title_Cheat_CountC:
		move.b	(Ctrl_1_Press).w,d0
		andi.b	#$20,d0
		beq.s	Title_Cheat_NoC
		addq.w	#1,(Correct_cheat_entries_2).w

Title_Cheat_NoC:
		tst.w	(Demo_Time_left).w
		beq.w	Demo
		andi.b	#$80,(Ctrl_1_Press).w
		beq.w	TitleScreen_Loop

Title_CheckLvlSel:
		tst.b	(Level_select_flag).w
		beq.w	PlayLevel
		moveq	#PalID_LevelSelect,d0
		bsr.w	PalLoad2

		clearRAM Horiz_Scroll_Buf,Horiz_Scroll_Buf_End-128
		move.l	d0,(Vscroll_Factor).w

		move	#$2700,sr
		lea	(VDP_data_port).l,a6
		move.l	#$60000003,(VDP_control_port).l
		move.w	#$3FF,d1

LevelSelect_ClearVRAM:
		move.l	d0,(a6)
		dbf	d1,LevelSelect_ClearVRAM
		bsr.w	LevelSelect_TextLoad

; ===========================================================================
; ---------------------------------------------------------------------------
; Level Select
; ---------------------------------------------------------------------------

LevelSelect_Loop:
		move.b	#VintID_Title,(Vint_routine).w
		bsr.w	WaitForVint
		bsr.w	LevelSelect_Controls
		bsr.w	RunPLC_RAM
		tst.l	(Plc_Buffer).w
		bne.s	LevelSelect_Loop
		andi.b	#$F0,(Ctrl_1_Press).w		; is A, B, C, or Start being pressed?
		beq.s	LevelSelect_Loop		; if not, branch
		move.w	#0,(Two_player_mode).w
		btst	#4,(Ctrl_1_Held).w		; is B being held?
		beq.s	.singlePlayer			; if not, branch
		move.w	#1,(Two_player_mode).w
; loc_3516:
.singlePlayer:
		move.w	(Level_select_zone).w,d0
		cmpi.w	#$14,d0				; have you selected item $14 (sound test)?
		bne.s	LevelSelect_StartGame		; if not, go to	Level/SS subroutine
		move.w	(Sound_test_sound).w,d0
		addi.w	#$80,d0
		tst.b	(Hidden_credits_flag).w		; is the Japanese credits cheat on?
		beq.s	LevelSelect_NoCheats		; if not, branch
		cmpi.w	#$9F,d0				; is sound $9F being played?
		beq.s	LevelSelect_PlayEnding		; if yes, branch
		cmpi.w	#$9E,d0				; is sound $9E being played?
		beq.s	LevelSelect_PlayCredits		; if yes, branch
; loc_353A:
LevelSelect_NoCheats:
		cmpi.w	#MusID__End+1,d0
		bcs.s	LevelSelect_PlaySound
		cmpi.w	#SndID__First,d0
		bcs.s	LevelSelect_Loop
; loc_3546:
LevelSelect_PlaySound:
		bsr.w	PlaySound
		bra.s	LevelSelect_Loop
; ===========================================================================
; loc_354C:
LevelSelect_PlayEnding:
		move.b	#GameModeID_S1Ending,(Game_Mode).w
		move.w	#$600,(Current_ZoneAndAct).w
		rts
; ===========================================================================
; loc_355A:
LevelSelect_PlayCredits:
		move.b	#GameModeID_S1Credits,(Game_Mode).w
		move.b	#MusID_Credits,d0
		bsr.w	PlaySound
		move.w	#0,(Ending_demo_number).w
		rts
; ===========================================================================
; loc_3570:
LevelSelect_StartGame:
		add.w	d0,d0
		move.w	LevelSelect_LevelOrder(pc,d0.w),d0
		bmi.w	LevelSelect_Loop
		cmpi.w	#$700,d0		; is level $700 loaded?
		bne.s	LevelSelect_StartZone	; if not, branch

; LevelSelect_SpecialStage:
		move.b	#GameModeID_SpecialStage,(Game_Mode).w
		clr.w	(Current_ZoneAndAct).w
		move.b	#3,(Life_count).w
		moveq	#0,d0
		move.w	d0,(Ring_count).w
		move.l	d0,(Timer).w
		move.l	d0,(Score).w
		move.l	#$1388,(Next_Extra_life_score).w
		rts
; ===========================================================================

LevelSelect_LevelOrder:
		dc.w	0,    1,    2
		dc.w	$200, $201, $202
		dc.w	$400, $401, $402
		dc.w	$100, $101, $102
		dc.w	$300, $301, $302
		dc.w	$500, $501, $103
		dc.w	$502
		dc.w	$700
		dc.w	$8000
		even
; ===========================================================================
; LevelSelect_Level:
LevelSelect_StartZone:
		andi.w	#$3FFF,d0
		move.w	d0,(Current_ZoneAndAct).w

PlayLevel:
		move.b	#GameModeID_Level,(Game_Mode).w
		move.b	#3,(Life_count).w
		moveq	#0,d0
		move.w	d0,(Ring_count).w
		move.l	d0,(Timer).w
		move.l	d0,(Score).w
		move.b	d0,(Current_SpecialStage).w
		move.b	d0,(Emerald_count).w
		move.l	d0,(Emeralds_array).w
		move.l	d0,(Emeralds_array+4).w		; Emeralds_array is only 6 bytes long, so this also clears
							; part of the oscillation bitfield
		move.b	d0,(Continue_count).w
		move.l	#$1388,(Next_Extra_life_score).w
		move.b	#CmdID_FadeOut,d0
		bsr.w	PlaySound
		rts
; End of function LevelSelect

