		bsr.w	WaitForVint
		bsr.w	RunPLC_RAM
		move.w	(MainCharacter+x_pos).w,d0
		addq.w	#2,d0
		move.w	d0,(MainCharacter+x_pos).w
		cmpi.w	#$1C00,d0
		bcs.s	RunDemo
