		lea	MZ_CameraSections+1(pc),a0
		move.w	(Camera_BG_Y_pos).w,d0
		add.w	d4,d0
		andi.w	#$3F0,d0
		bsr.w	Draw_BackgroundRow
		movem.l	(sp)+,d4-d6
		; after we finish drawing the current row, head down to the next one
		addi.w	#16,d4
		dbf	d6,loc_71DE
		rts
