BGCameraSections:
		dc.w Camera_BG_X_pos		; Background A (static)
		dc.w Camera_BG_X_pos		; Background A (dynamic)
		dc.w Camera_BG2_X_pos		; Background B (dynamic)
		dc.w Camera_BG3_X_pos		; Background C (dynamic)

