Draw_BackgroundRow:
		lsr.w	#4,d0
		move.b	(a0,d0.w),d0
		movea.w	BGCameraSections(pc,d0.w),a3	; get camera type
		beq.s	.staticRow		; if it's staic, branch

		moveq	#-16,d5			; start drawing a row of blocks
		movem.l	d4-d5,-(sp)
		bsr.w	CalculateVRAMPosition
		movem.l	(sp)+,d4-d5
		move	#$2700,sr
		bsr.w	sub_6D8C
		move	#$2300,sr
		rts
