MainLevelLoadBlock:
		moveq	#0,d0
		move.b	(Current_Zone).w,d0
		lsl.w	#4,d0
		lea	(LevelArtPointers).l,a2
		lea	(a2,d0.w),a2
		move.l	a2,-(sp)
		addq.l	#4,a2
		movea.l	(a2)+,a0
		tst.b	(Current_Zone).w		; is this Green Hill Zone?
		beq.s	.uncompressedBlocks		; if yes... jump to where we were going anyways
		bra.s	.uncompressedBlocks
; ---------------------------------------------------------------------------
; Sonic 1 compresses its 16x16 blocks in Enigma; Sonic 2 Nick Arcade leaves
; them uncompressed, likely so that the developers wouldn't have to recompress
; them every time a change was made. Based on the above code, Green Hill had
; its blocks compressed in Enigma up to a certain point
; MainLevelLoadBlock_Skip16Convert:
.enigmaBlocks:
		lea	(Block_Table).w,a1
		move.w	#0,d0
		bsr.w	EniDec
		bra.s	loc_72C2
; ---------------------------------------------------------------------------
; MainLevelLoadBlock_Convert16:
.uncompressedBlocks:
		lea	(Block_Table).w,a1
		move.w	#(Block_Table_End-Block_Table)/2-1,d2
; MainLevelLoadBlock_ConvertLoop:
.uncompressedLoop:
		move.w	(a0)+,d0
		tst.w	(Two_player_mode).w
		beq.s	.notTwoPlayer
		move.w	d0,d1
		andi.w	#$F800,d0
		andi.w	#$7FF,d1
		lsr.w	#1,d1
		or.w	d1,d0
; MainLevelLoadBlock_Not2p:
.notTwoPlayer:
		move.w	d0,(a1)+
		dbf	d2,.uncompressedLoop

loc_72C2:
		cmpi.b	#5,(Current_Zone).w
		bne.s	.loadChunks
		lea	(Block_Table+$980).w,a1
		lea	(Map16_HTZ).l,a0
		move.w	#$3FF,d2
; loc_72D8:
.uncompressedLoop2:
		move.w	(a0)+,d0
		tst.w	(Two_player_mode).w
		beq.s	.notTwoPlayer2
		move.w	d0,d1
		andi.w	#$F800,d0
		andi.w	#$7FF,d1
		lsr.w	#1,d1
		or.w	d1,d0
; loc_72EE:
.notTwoPlayer2:
		move.w	d0,(a1)+
		dbf	d2,.uncompressedLoop2
; loc_72F4:
.loadChunks:
		movea.l	(a2)+,a0
		cmpi.b	#2,(Current_Zone).w
		beq.s	.uncompressedChunks
		cmpi.b	#3,(Current_Zone).w
		beq.s	.uncompressedChunks
		cmpi.b	#4,(Current_Zone).w
		beq.s	.uncompressedChunks
		cmpi.b	#5,(Current_Zone).w
		beq.s	.uncompressedChunks
		move.l	a2,-(sp)
		moveq	#0,d1
		moveq	#0,d2
		move.w	(a0)+,d0
		lea	(a0,d0.w),a1
		lea	(Chunk_Table).l,a2
		lea	(Level_Layout).w,a3
; loc_732C:
.chameleonChunks:
		bsr.w	ChaDec
		tst.w	d0
		bmi.s	.chameleonChunks
		movea.l	(sp)+,a2
		bra.s	.loadLevelAndPalette
; ---------------------------------------------------------------------------
; loc_7338:
.uncompressedChunks:
		lea	(Chunk_Table).l,a1
		move.w	#(Chunk_Table_End-Chunk_Table)/4-1,d0
; loc_7342:
.uncompressedLoop3:
		move.w	(a0)+,(a1)+
		dbf	d0,.uncompressedLoop3
; loc_7348:
.loadLevelAndPalette:
		bsr.w	LevelLayoutLoad
		move.w	(a2)+,d0
		move.w	(a2),d0
		andi.w	#$FF,d0
		cmpi.w	#$103,(Current_ZoneAndAct).w
		bne.s	.notLZ4
		moveq	#PalID_LZ4,d0
; loc_735E:
.notLZ4:
		cmpi.w	#$501,(Current_ZoneAndAct).w
		beq.s	.notSBZ2
		cmpi.w	#$502,(Current_ZoneAndAct).w
		bne.s	.loadPaletteAndPLC
; loc_736E:
.notSBZ2:
		moveq	#PalID_SBZ2,d0
; loc_7370:
.loadPaletteAndPLC:
		bsr.w	PalLoad1
		movea.l	(sp)+,a2
		addq.w	#4,a2
		moveq	#0,d0
		move.b	(a2),d0
		beq.s	locret_7382
		bsr.w	LoadPLC

locret_7382:
