		lea	($FE0000).l,a1
		lea	(Chunk_Table&$FFFFFF).l,a2
		move.w	#$3F,d1	; '?'

loc_7496:				; CODE XREF: ROM:0000749Aj
		move.w	#0,(a2)+
		dbf	d1,loc_7496
